/**
 * Detect a cycle in the dependency graph using a depth-first search that
 * visits tasks and their dependencies in ascending name order, matching the
 * order the task specification requires.
 *
 * Throws a `CliError` with exit code 3 describing the first cycle found.
 */
function checkForCycle(names, deps) {
  const state = new Map(names.map((n) => [n, 0])) // 0 unvisited, 1 in-progress, 2 done
  const stack = []

  function visit(u) {
    state.set(u, 1)
    stack.push(u)
    const ds = [...(deps.get(u) || [])].sort()
    for (const v of ds) {
      const s = state.get(v)
      if (s === 1) {
        const idx = stack.indexOf(v)
        const cyclePath = stack.slice(idx)
        cyclePath.push(v)
        throw new CliError(`error: cycle: ${cyclePath.join(' -> ')}`, 3)
      } else if (s === 0) {
        visit(v)
      }
    }
    stack.pop()
    state.set(u, 2)
  }

  for (const n of names) {
    if (state.get(n) === 0) visit(n)
  }
}

/**
 * Compute the schedule for the unlimited-worker case: each task's wave
 * (depth), start time and finish time.
 */
export function computeSchedule(tasks, deps) {
  const names = [...tasks.keys()].sort()

  checkForCycle(names, deps)

  const depthMemo = new Map()
  const startMemo = new Map()
  const finishMemo = new Map()

  function depth(n) {
    if (depthMemo.has(n)) return depthMemo.get(n)
    let d = 0
    for (const dep of deps.get(n) || []) d = Math.max(d, depth(dep) + 1)
    depthMemo.set(n, d)
    return d
  }

  function finish(n) {
    if (finishMemo.has(n)) return finishMemo.get(n)
    const f = start(n) + tasks.get(n)
    finishMemo.set(n, f)
    return f
  }

  function start(n) {
    if (startMemo.has(n)) return startMemo.get(n)
    let s = 0
    for (const dep of deps.get(n) || []) s = Math.max(s, finish(dep))
    startMemo.set(n, s)
    return s
  }

  for (const n of names) {
    depth(n)
    finish(n)
  }

  const total = names.length === 0 ? 0 : Math.max(...names.map((n) => finish(n)))

