  for (const [target, set] of deps) {
    for (const d of set) {
      if (!dependents.has(d)) dependents.set(d, [])
      dependents.get(d).push(target)
    }
  }

  const memo = new Map()
  function priority(n) {
    if (memo.has(n)) return memo.get(n)
    let best = 0
    for (const child of dependents.get(n) || []) best = Math.max(best, priority(child))
    const p = tasks.get(n) + best
    memo.set(n, p)
    return p
  }

  for (const n of tasks.keys()) priority(n)
  return priority
}

/**
 * Simulate the build on `workerCount` workers, returning one array of
 * `{ name, start, finish }` entries per worker, in the order each worker ran
 * them, plus the overall makespan.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriorities(tasks, deps)
  const names = [...tasks.keys()]

  const workerFree = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finishTime = new Map()
  const started = new Set()
  const remaining = new Set(names)

  let currentTime = 0

  function isReady(name, time) {
    for (const d of deps.get(name) || []) {
      const f = finishTime.get(d)
      if (f === undefined || f > time) return false
    }
    return true
  }

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      let bestPriority = -Infinity
      for (const name of remaining) {
        if (!isReady(name, currentTime)) continue
        const p = priority(name)
        if (best === null || p > bestPriority || (p === bestPriority && name < best)) {
          best = name
          bestPriority = p
        }
      }
      if (best === null) break

      const start = currentTime
      const finish = start + tasks.get(best)
      workerLog[freeWorker].push({ name: best, start, finish })
      workerFree[freeWorker] = finish
      finishTime.set(best, finish)
      started.add(best)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFree[i] > currentTime) next = Math.min(next, workerFree[i])
