/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parser.js'
import { computeSchedule } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9]\d*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function runWaves(tasks, deps) {
  const { names, depth, total } = computeSchedule(tasks, deps)
  const waves = []
  for (const n of names) {
    const d = depth(n)
    if (!waves[d]) waves[d] = []
    waves[d].push(n)
  }
  const lines = []
  for (let k = 0; k < waves.length; k++) {
    lines.push(`wave ${k}: ${waves[k].join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + (lines.length ? '\n' : '')
}

function runExplain(tasks, deps) {
  const { names, depth, start, finish, total } = computeSchedule(tasks, deps)
  const lines = []
  for (const n of names) {
    lines.push(`${n} start=${start(n)} finish=${finish(n)} depth=${depth(n)}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, deps, workers) {
  // Cycle detection is required before packing too.
  computeSchedule(tasks, deps)
  const { workerLog, makespan } = pack(tasks, deps, workers)
  const lines = []
  for (let i = 0; i < workers; i++) {
    const entries = workerLog[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const { mode, workers } = parseArgs(argv)

  const input = fs.readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)

  let output
  if (mode === 'waves') output = runWaves(tasks, deps)
  else if (mode === 'explain') output = runExplain(tasks, deps)
  else output = runPack(tasks, deps, workers)

  process.stdout.write(output)
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
}
