import { parseGraph } from './parser.js'
import { computeSchedule } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9]\d*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function runWaves(tasks, deps) {
  const { names, depth, total } = computeSchedule(tasks, deps)
  const waves = []
  for (const n of names) {
    const d = depth(n)
    if (!waves[d]) waves[d] = []
    waves[d].push(n)
  }
  const lines = []
  for (let k = 0; k < waves.length; k++) {
    lines.push(`wave ${k}: ${waves[k].join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + (lines.length ? '\n' : '')
}

function runExplain(tasks, deps) {
  const { names, depth, start, finish, total } = computeSchedule(tasks, deps)
  const lines = []
  for (const n of names) {
    lines.push(`${n} start=${start(n)} finish=${finish(n)} depth=${depth(n)}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

